#include <bits/stdc++.h>

using namespace std;

#define inf (long long)1e15
#define ll long long
#define all(x) x.begin(), x.end()
#define x first
#define y second

const int MAX_SIZE = 200010;
const int LIMIT = 1000010;

vector<ll> pattern({0ll});
int minimal_moves = LIMIT;

void dfs(ll x, int count) {
    if (count > minimal_moves)
        return;
    if (x == 0) {
        minimal_moves = count;
        return;
    }
    auto it_lower = lower_bound(all(pattern), x);
    auto it_upper = upper_bound(all(pattern), x);
    if (it_lower == it_upper) it_lower--;
    ll diff_a = x - *it_lower;
    int cost = it_lower - pattern.begin();
    ll diff_b = *it_upper - x;
    dfs(x % *it_lower, count + cost * (x / *it_lower));
    dfs(diff_b, count + cost + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll n;
    cin >> n;
    for (int i = 1; i <= 16; ++i) {
        pattern.push_back(pattern.back() * 10 + 1);
    }
    dfs(n, 0);
    cout << minimal_moves << "\n";
    return 0;
}
